quiz.answer:
package main

import (
	"bufio"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Header struct {
	Alg string `json:"alg"`
}

type Claims struct {
	User string `json:"user"`
	Exp  int64  `json:"exp"`
}

// verify は検証に通ればユーザー名と true を返す
func verify(token, secret string, now int64) (string, bool) {
	enc := base64.RawURLEncoding
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return "", false
	}

	// ① アルゴリズムはサーバーが決める。HS256 以外(none を含む)は拒否
	hb, err := enc.DecodeString(parts[0])
	if err != nil {
		return "", false
	}
	var h Header
	if json.Unmarshal(hb, &h) != nil || h.Alg != "HS256" {
		return "", false
	}

	// ② 署名を再計算して比べる(hmac.Equal で比較)
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write([]byte(parts[0] + "." + parts[1]))
	got, err := enc.DecodeString(parts[2])
	if err != nil || !hmac.Equal(got, mac.Sum(nil)) {
		return "", false
	}

	// ③ 期限を確かめる(exp がない・過ぎているものは拒否)
	pb, err := enc.DecodeString(parts[1])
	if err != nil {
		return "", false
	}
	var c Claims
	if json.Unmarshal(pb, &c) != nil || c.Exp <= now {
		return "", false
	}
	return c.User, true
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	secret := sc.Text()
	sc.Scan()
	now, _ := strconv.ParseInt(strings.TrimSpace(sc.Text()), 10, 64)
	sc.Scan()
	token := strings.TrimSpace(sc.Text())

	if user, ok := verify(token, secret, now); ok {
		fmt.Println("OK " + user)
	} else {
		fmt.Println("NG")
	}
}

